CREATE EXTENSION IF NOT EXISTS postgis;

DROP TABLE IF EXISTS cooling_centers;
DROP TABLE IF EXISTS rail_stations;
DROP TABLE IF EXISTS rail_lines;
DROP TABLE IF EXISTS cities;

CREATE TABLE cities (
  name       text PRIMARY KEY,
  county     text NOT NULL,
  pop_2020   integer,                 
  sq_miles   numeric(8,2),
  geom       geometry(MultiPolygon, 4326) NOT NULL
);

CREATE TABLE cooling_centers (
  id           serial PRIMARY KEY,
  name         text NOT NULL,
  organization text,
  address      text,
  city         text,                  
  kind         text NOT NULL,         
  hours        text,
  sunday_open  text,                  
  phone        text,
  pets         text,                  
  wheelchair   text,                  
  services     text,
  season_year  integer,
  geom         geometry(Point, 4326) NOT NULL
);

CREATE TABLE rail_stations (
  station_id     integer PRIMARY KEY,
  name           text NOT NULL,
  city           text,
  service        text,                
  status         text,
  water_fountain boolean,
  restroom       boolean,
  geom           geometry(Point, 4326) NOT NULL
);

CREATE TABLE rail_lines (
  id     integer PRIMARY KEY,
  route  text,
  geom   geometry(MultiLineString, 4326) NOT NULL
);









CREATE INDEX cooling_centers_geom_idx ON cooling_centers USING GIST (geom);
CREATE INDEX rail_stations_geom_idx   ON rail_stations   USING GIST (geom);
CREATE INDEX rail_lines_geom_idx      ON rail_lines      USING GIST (geom);
CREATE INDEX cities_geom_idx          ON cities          USING GIST (geom);


SELECT 'cities' AS table_name, count(*) FROM cities
UNION ALL SELECT 'cooling_centers', count(*) FROM cooling_centers
UNION ALL SELECT 'rail_stations',   count(*) FROM rail_stations
UNION ALL SELECT 'rail_lines',      count(*) FROM rail_lines;
